using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class SystemHealthPage:UserControl{FlowLayoutPanel body;public SystemHealthPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;body=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(8)};Controls.Add(body);RefreshHealth();}void Add(string a,string b){var p=Ui.Card();p.Width=650;p.Height=76;var l=Ui.Label(a+"   "+b,12,true);p.Controls.Add(l);body.Controls.Add(p);}void RefreshHealth(){body.Controls.Clear();try{Database.Scalar("SELECT 1");Add(L.Fa?"پایگاه داده":"Database","OK");}catch(Exception ex){Add(L.Fa?"پایگاه داده":"Database","ERROR: "+ex.Message);}Add(L.Fa?"نسخه .NET":".NET version",Environment.Version.ToString());Add(L.Fa?"حافظه برنامه":"Process memory",(Process.GetCurrentProcess().WorkingSet64/1024/1024)+" MB");Add(L.Fa?"سیستم عامل":"OS",Environment.OSVersion.ToString());Add(L.Fa?"مسیر برنامه":"Application path",Application.StartupPath);}}
}